def format_shipping_address(data):
    name = data.get('shipping_name', '')
    street = data.get('shipping_street', '')
    city = data.get('shipping_city', '')
    postcode = data.get('shipping_postcode', '')
    if 'billing_postcode' in data:
        data['billing_postcode'] = postcode
    return '\n'.join([name, street, f"{city} {postcode}".strip()])
